insert into krakow.translation_cache (cache_key, source_lang, target_lang, source_text, translated_text, engine, model, glossary_version)
select encode(sha256(convert_to('manual|en|pl|' || v.en, 'UTF8')), 'hex'), 'en', 'pl', v.en, v.pl, 'manual', 'manual', '1'
  from (values
    ('Kraków open data: sports infrastructure of schools 2023/2024', 'Otwarte dane Krakowa: infrastruktura sportowa szkół 2023/2024'),
    ('Open data of Gmina Miejska Kraków (otwartedane.um.krakow.pl): free reuse with the credit and the dates of creation and acquisition; addresses located with OpenStreetMap address points (ODbL 1.0)', 'Dane otwarte Gminy Miejskiej Kraków (otwartedane.um.krakow.pl): swobodne wykorzystanie z podaniem źródła oraz dat wytworzenia i pozyskania; adresy zlokalizowano w punktach adresowych OpenStreetMap (ODbL 1.0)'),
    ('Gmina Miejska Kraków, otwartedane.um.krakow.pl; © OpenStreetMap contributors (addresses located with address points)', 'Gmina Miejska Kraków, otwartedane.um.krakow.pl; © współtwórcy OpenStreetMap (adresy zlokalizowano w punktach adresowych)'),
    ('Pitches, courts, running tracks and other sports grounds of the schools in the city''s register, added up per district. A school belongs to the district its address is in.', 'Boiska, korty, bieżnie i inne tereny sportowe szkół z rejestru miasta, zsumowane w dzielnicach. Szkoła należy do dzielnicy, w której leży jej adres.'),
    ('67 of 973 schools in the register could not be placed in a district from their address and are left out.', '67 z 973 szkół z rejestru nie udało się przypisać do dzielnicy na podstawie adresu, więc ich nie liczymy.'),
    ('OpenStreetMap emergency=defibrillator with access=yes or permissive.', 'OpenStreetMap emergency=defibrillator z access=yes lub permissive.'),
    ('Only points tagged as publicly accessible are counted (75 of 329 mapped in the city). Volunteers map them, so the real number may be higher. Some are inside buildings with opening hours.', 'Liczymy tylko punkty oznaczone jako publicznie dostępne (75 z 329 zmapowanych w mieście). Mapują je wolontariusze, więc prawdziwa liczba może być wyższa. Część jest w budynkach, z godzinami otwarcia.'),
    ('pitches, courts and tracks', 'boiska, korty i bieżnie')
  ) as v(en, pl)
